const binaryData = $input.first().binary;
const binaryKey = Object.keys(binaryData)[0];
const fileData = binaryData[binaryKey];
const base64Pdf = fileData.data;

const webhookData = $('Webhook').first().json.body;

const systemPrompt = "You are extracting borrower information from a Uniform Residential Loan Application (Form 1003). Extract the following fields and return ONLY valid JSON, no markdown formatting:\n\n{\n  \"borrower_names\": [\"First Last\"],\n  \"borrower_emails\": [\"email@example.com\"],\n  \"borrower_phones\": [\"(555) 123-4567\"],\n  \"property_address\": \"123 Main St, City, ST 12345\",\n  \"purchase_price\": \"$350,000\",\n  \"loan_amount\": \"$280,000\"\n}\n\nIf there are two borrowers (co-borrower), include both in the arrays. If a field is not found, use null.";

const userPrompt = "Extract borrower details from this loan application PDF.";

const claudeBody = {
  model: "claude-sonnet-4-5-20251022",
  max_tokens: 1024,
  system: systemPrompt,
  messages: [
    {
      role: "user",
      content: [
        {
          type: "document",
          source: {
            type: "base64",
            media_type: "application/pdf",
            data: base64Pdf
          }
        },
        {
          type: "text",
          text: userPrompt
        }
      ]
    }
  ]
};

return [{
  json: {
    claudeBody,
    webhookData
  }
}];

const claudeResponse = $input.first().json;
const webhookData = $('Build Claude Request').first().json.webhookData;

let extractedText = '';
if (claudeResponse.content && claudeResponse.content.length > 0) {
  extractedText = claudeResponse.content[0].text;
}

// Parse JSON from Claude response - strip markdown code fences if present
let cleanText = extractedText.trim();
if (cleanText.startsWith('```')) {
  cleanText = cleanText.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '').trim();
}

let extracted;
try {
  extracted = JSON.parse(cleanText);
} catch (e) {
  extracted = {
    borrower_names: [webhookData.borrower_first_name || 'there'],
    borrower_emails: [webhookData.borrower_email || ''],
    borrower_phones: [],
    property_address: null,
    purchase_price: null,
    loan_amount: null
  };
}

// Build display names
const borrowerNames = extracted.borrower_names || [];
const firstNames = borrowerNames.map(n => n.split(' ')[0]);
const greeting = firstNames.length > 1 ? firstNames.join(' and ') : (firstNames[0] || 'there');
const personalizedClosing = firstNames.length > 1 ? ' with you both' : '';

// Use extracted email or fall back to webhook
const borrowerEmail = (extracted.borrower_emails && extracted.borrower_emails[0]) || webhookData.borrower_email || '';

// Agent info from webhook
const agentFirst = webhookData.agent_first_name || '[Agent]';
const pronoun = webhookData.pronoun || 'them';
const pronounContraction = pronoun === 'them' ? "they're" : (pronoun === 'her' ? "she's" : "he's");
const timeframeContext = webhookData.timeframe_context || 'recently';
const loanId = webhookData.loan_id || '';

return [{
  json: {
    greeting,
    personalizedClosing,
    borrowerEmail,
    borrowerNames,
    agentFirst,
    pronoun,
    pronounContraction,
    timeframeContext,
    loanId,
    extracted
  }
}];

const d = $input.first().json;

const emailHtml = '<p>Hi ' + d.greeting + ',</p>' +
  '<p>My name is Adam Styer \u2014 ' + d.agentFirst + ' shared your information with me ' + d.timeframeContext + ' and mentioned you\'d be reaching out. I just saw your application come through, so I wanted to connect and introduce myself.</p>' +
  '<p>First off \u2014 you\'re in great hands with ' + d.agentFirst + '. I\'ve known ' + d.pronoun + ' for a while now and ' + d.pronounContraction + ' a great agent and a great person.</p>' +
  '<p>I\'m going to start reviewing your application and pulling together your options. Before we get too far down the road, I\'d love to hop on a quick call to walk you through how we work, answer any questions, and make sure we\'re locked in on the right strategy for your purchase.</p>' +
  '<p>Feel free to call me directly at <a href="tel:5129566010">512-956-6010</a>, or grab a time on my calendar here: <a href="https://calendly.com/adamstyer/15minutes">Schedule a Call</a></p>' +
  '<p>Looking forward to connecting' + d.personalizedClosing + '.</p>' +
  '<p>Adam Styer<br>Senior Loan Officer | Mortgage Solutions LP<br>NMLS# 513013<br>(512) 956-6010<br>adam@thestyerteam.com</p>';

const subject = 'Got Your Application \u2013 Adam Styer | Mortgage Solutions LP';

return [{
  json: {
    emailHtml,
    subject,
    borrowerEmail: d.borrowerEmail,
    greeting: d.greeting,
    agentFirst: d.agentFirst,
    loanId: d.loanId,
    extracted: d.extracted
  }
}];
